-- TESTING only: fixtures, actions and permission changes roll back.
begin;
create function pg_temp.wh_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Warehouse assertion: %',label;end if;end$$;
create function pg_temp.wh_error(statement text,expected text) returns void language plpgsql as $$begin
 begin execute statement;exception when others then if sqlerrm=expected then return;end if;raise exception 'expected %, got %',expected,sqlerrm;end;
 raise exception 'expected % but succeeded',expected;end$$;
do $test$
declare f uuid;actor uuid;p uuid;ext uuid;hybrid uuid;raw uuid;semi uuid;wip uuid;missing uuid;r uuid;again uuid;retry uuid;info jsonb;x jsonb;order_id uuid;filter jsonb;begin
 select m.factory_id,m.user_id into f,actor from public.memberships m join public.factories fac on fac.id=m.factory_id where fac.is_demo and m.status='approved' and m.is_owner limit 1;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 insert into public.products(factory_id,name,name_ar,code,unit,stock_unit,minimum_stock,maximum_stock,supply_mode)
 values(f,'Warehouse zero pipe','أنبوب صفري','WH-'||gen_random_uuid(),'meter','meter',10,50,'MAKE_TO_STOCK') returning id into p;
 insert into public.products(factory_id,name,code,unit,stock_unit,supply_source,minimum_stock,maximum_stock,supply_mode)
 values(f,'Warehouse external','WH-'||gen_random_uuid(),'piece','piece','EXTERNAL',10,50,'MAKE_TO_STOCK') returning id into ext;
 insert into public.products(factory_id,name,code,unit,stock_unit,supply_source,minimum_stock,maximum_stock,supply_mode)
 values(f,'Warehouse hybrid','WH-'||gen_random_uuid(),'meter','meter','BOTH',10,50,'MAKE_TO_STOCK') returning id into hybrid;
 insert into public.products(factory_id,name,code,unit,stage) values(f,'Temporary WIP','WH-'||gen_random_uuid(),'piece','wip') returning id into wip;
 insert into public.products(factory_id,name,code,unit,stock_unit) values(f,'No minimum','WH-'||gen_random_uuid(),'meter','meter') returning id into missing;
 raw:=public.create_warehouse_material(f,jsonb_build_object('name','Warehouse zero resin','code','WH-'||gen_random_uuid(),'unit','kg'),gen_random_uuid());
 insert into public.materials(factory_id,name,code,unit,inventory_kind) values(f,'Legacy Warehouse sleeve','WH-'||gen_random_uuid(),'piece','SEMI_FINISHED') returning id into semi;
 perform pg_temp.wh_error(format('select public.create_warehouse_material(%L,%L::jsonb,%L)',f,jsonb_build_object('name','Invalid new semi','code','WH-'||gen_random_uuid(),'unit','piece','inventory_kind','SEMI_FINISHED'),gen_random_uuid()),'fulfillment_invalid');
 perform public.configure_warehouse_material(f,raw,0,null);
 select value into x from private.warehouse_inventory_rows(f) value where value->>'id'=p::text;
 perform pg_temp.wh_assert((x->>'on_hand')::numeric=0 and x->>'item_type'='FINISHED_GOOD','finished catalogue zero no history');
 perform pg_temp.wh_assert(x->>'minimum_status'='AT_OR_BELOW_MIN' and (x->>'can_produce')::boolean,'manufactured low action');
 select value into x from private.warehouse_inventory_rows(f) value where value->>'id'=raw::text;
 perform pg_temp.wh_assert((x->>'on_hand')::numeric=0 and x->>'item_type'='RAW_MATERIAL','raw zero no history');
 perform pg_temp.wh_assert(x->>'minimum_status'='AT_OR_BELOW_MIN' and x->>'replenishment_status'='EXTERNAL_REQUIRED' and not (x->>'can_produce')::boolean,'raw equals minimum external');
 perform pg_temp.wh_assert((x->>'incoming')::numeric=0 and x->>'maximum_stock' is null,'no active ordered purchase and maximum remains NULL');
 select value into x from private.warehouse_inventory_rows(f) value where value->>'id'=semi::text;
 perform pg_temp.wh_assert((x->>'on_hand')::numeric=0 and x->>'item_type'='SEMI_FINISHED','durable semi catalogue');
 perform pg_temp.wh_assert(not exists(select 1 from private.warehouse_inventory_rows(f) value where value->>'id'=wip::text),'temporary WIP excluded');
 select value into x from private.warehouse_inventory_rows(f) value where value->>'id'=missing::text;
 perform pg_temp.wh_assert(x->>'minimum_status'='NOT_CONFIGURED' and not (x->>'can_produce')::boolean,'no minimum not flagged');
 perform private.replenish_finished(f,p);perform private.replenish_finished(f,p);
 perform pg_temp.wh_assert(not exists(select 1 from public.production_orders where product_id=p),'no automatic request');
 perform pg_temp.wh_error(format('select private.fulfillment_production(%L,%L,%L,50,%L,null,null)',f,p,'meter','STOCK_REPLENISHMENT'),'warehouse_confirmation_required');
 perform pg_temp.wh_error(format('insert into public.production_requests(factory_id,code,name,requested_by,requested_by_name,priority,request_type) values(%L,%L,%L,%L,%L,%L,%L)',f,'','Forged',actor,'Test','low','STOCK_REPLENISHMENT'),'warehouse_confirmation_required');
 perform public.receive_warehouse_stock(f,p,'finished','meter',10,'opening_balance');
 select value into x from private.warehouse_inventory_rows(f) value where value->>'id'=p::text;
 perform pg_temp.wh_assert(x->>'minimum_status'='AT_OR_BELOW_MIN' and (x->>'projected')::numeric=10,'equality flagged');
 perform public.receive_warehouse_stock(f,p,'finished','meter',1,'external_receipt');
 select value into x from private.warehouse_inventory_rows(f) value where value->>'id'=p::text;
 perform pg_temp.wh_assert(x->>'minimum_status'='ABOVE_MIN','above min normal');
 perform public.adjust_finished_stock(f,p,'meter',-2,'Warehouse regression');
 select value into x from private.warehouse_inventory_rows(f) value where value->>'id'=p::text;
 perform pg_temp.wh_assert((x->>'projected')::numeric=private.projected_finished(f,p,'meter') and x->>'minimum_status'='AT_OR_BELOW_MIN','same authoritative projection');
 perform pg_temp.wh_error(format('select public.confirm_warehouse_replenishment(%L,%L,%L,%L,0,50,%L)',f,p,'produce','meter',gen_random_uuid()),'warehouse_stock_changed');
 perform pg_temp.wh_error(format('select public.confirm_warehouse_replenishment(%L,%L,%L,%L,9,50,%L)',f,p,'produce','piece',gen_random_uuid()),'fulfillment_product');
 perform pg_temp.wh_error(format('select public.confirm_warehouse_replenishment(%L,%L,%L,%L,9,50,%L)',f,p,'produce','meter',gen_random_uuid()),'fulfillment_invalid');
 retry:=gen_random_uuid();r:=public.confirm_warehouse_replenishment(f,p,'produce','meter',9,41,retry);
 perform pg_temp.wh_assert(r=public.confirm_warehouse_replenishment(f,p,'produce','meter',9,41,retry),'same retry identity');
 again:=public.confirm_warehouse_replenishment(f,p,'produce','meter',9,41,gen_random_uuid());
 perform pg_temp.wh_assert(r=again and (select count(*)=1 from public.production_orders where product_id=p),'different retry no duplicate');
 perform pg_temp.wh_assert((select request_type='STOCK_REPLENISHMENT' and requested_by=actor and priority='low' and required_by is null from public.production_requests where id=r),'stock origin actor no deadline');
 perform pg_temp.wh_assert((select target_quantity=41 and unit='meter' and line_id is null and start_time is null and actual_start is null from public.production_orders where request_id=r),'manual Planning');
 select value into x from private.warehouse_inventory_rows(f) value where value->>'id'=p::text;
 perform pg_temp.wh_assert(x->>'replenishment_status'='ALREADY_REQUESTED' and (x->>'incoming')::numeric=41 and (x->>'projected')::numeric=50 and not (x->>'can_produce')::boolean,'incoming coverage suppresses action');
 perform public.configure_product_stock(f,p,'MAKE_TO_STOCK','meter',20,60);
 perform pg_temp.wh_assert((select target_quantity=41 from public.production_orders where request_id=r),'no automatic resize');
 select value into x from private.warehouse_inventory_rows(f) value where value->>'id'=ext::text;
 perform pg_temp.wh_assert(x->>'replenishment_status'='EXTERNAL_REQUIRED' and not (x->>'can_produce')::boolean,'external no production');
 perform pg_temp.wh_error(format('select public.confirm_warehouse_replenishment(%L,%L,%L,%L,0,50,%L)',f,ext,'produce','piece',gen_random_uuid()),'fulfillment_source_decision');
 select value into x from private.warehouse_inventory_rows(f) value where value->>'id'=hybrid::text;
 perform pg_temp.wh_assert(x->>'replenishment_status'='SOURCING_REQUIRED','hybrid choice required');
 perform public.confirm_warehouse_replenishment(f,hybrid,'external','meter',0,null,gen_random_uuid());
 perform pg_temp.wh_assert(not exists(select 1 from public.production_orders where product_id=hybrid),'external choice no production');
 select value into x from private.warehouse_inventory_rows(f) value where value->>'id'=hybrid::text;
 perform pg_temp.wh_assert(x->>'replenishment_status'='SOURCING_REQUIRED' and not (x->>'external_chosen')::boolean,'legacy external decision is retained without fabricating a Purchase Request');
 r:=public.confirm_warehouse_replenishment(f,hybrid,'produce','meter',0,50,gen_random_uuid());
 perform pg_temp.wh_assert((select request_type='STOCK_REPLENISHMENT' from public.production_requests where id=r),'hybrid produce confirmed');
 perform pg_temp.wh_assert(not exists(select 1 from public.purchase_requisitions where product_id=hybrid),'internal sourcing creates no Purchase Request');
 perform public.configure_product_stock(f,missing,'MAKE_TO_STOCK','meter',5,null);
 perform pg_temp.wh_error(format('select public.confirm_warehouse_replenishment(%L,%L,%L,%L,0,null,%L)',f,missing,'produce','meter',gen_random_uuid()),'fulfillment_invalid');
 r:=public.confirm_warehouse_replenishment(f,missing,'produce','meter',0,17,gen_random_uuid());
 perform pg_temp.wh_assert((select target_quantity=17 from public.production_orders where request_id=r),'missing max explicit quantity');
 order_id:=public.create_sales_order(f,jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',8,'unit','meter'))));
 perform public.approve_sales_order(f,order_id);
 select value into x from private.warehouse_inventory_rows(f) value where value->>'id'=p::text;
 perform pg_temp.wh_assert((x->>'on_hand')::numeric=9 and (x->>'reserved')::numeric=8 and (x->>'available')::numeric=1,'reservation math');
 perform pg_temp.wh_assert((x->>'incoming')::numeric=41 and (x->>'projected')::numeric=42,'projection Sales deductions');
 for filter in select value from jsonb_array_elements('[{"name":"zero pipe"},{"name":"أنبوب"},{"code":"WH-"},{"item_type":["FINISHED_GOOD","RAW_MATERIAL"]},{"supply_source":["MANUFACTURED"]},{"unit":["meter"]},{"on_hand":{"op":"eq","value":9}},{"reserved":{"op":"positive"}},{"available":{"op":"gt","value":0}},{"incoming":{"op":"range","value":40,"to":42}},{"projected":{"op":"lt","value":43}},{"minimum_stock":{"op":"eq","value":20}},{"maximum_stock":{"op":"configured"}},{"minimum_status":["ABOVE_MIN"]},{"replenishment_status":["ALREADY_REQUESTED"]},{"name":"zero pipe","reserved":{"op":"gt","value":0},"available":{"op":"eq","value":1}}]'::jsonb) loop
 perform pg_temp.wh_assert(private.warehouse_filter_matches(x,filter),'filter '||filter::text);end loop;
 perform pg_temp.wh_assert(not private.warehouse_filter_matches(x,'{"name":"zero pipe","reserved":{"op":"gt","value":8}}'),'AND excludes mismatch');
 perform pg_temp.wh_assert(private.warehouse_filter_matches(jsonb_build_object('minimum_stock',null),'{"minimum_stock":{"op":"not_configured"}}'),'NULL filter');
 info:=public.warehouse_inventory(f,1,jsonb_build_object('name','zero pipe','reserved',jsonb_build_object('op','positive')),'on_hand','desc');
 perform pg_temp.wh_assert((info->>'total')::integer=1 and info->'rows'->0->>'id'=p::text,'server filtering');
 perform pg_temp.wh_assert(public.warehouse_inventory(f,1,'{}')->>'total' is not null,'clear all');
 perform pg_temp.wh_error(format('select public.warehouse_inventory(%L,1,%L::jsonb)',f,'{"on_hand":{"op":"range","value":10,"to":1}}'),'fulfillment_invalid');
 perform pg_temp.wh_error(format('select public.warehouse_inventory(%L,1,%L::jsonb)',f,'{"unknown":"bad"}'),'fulfillment_invalid');
 perform pg_temp.wh_error(format('select public.warehouse_inventory(%L,1,%L::jsonb,%L)',f,'{}','name;drop table products'),'fulfillment_invalid');
 insert into public.materials(factory_id,name,code,unit) select f,'Warehouse paging '||g,'WH-PAGE-'||gen_random_uuid(),'kg' from generate_series(1,57) g;
 info:=public.warehouse_inventory(f,1,'{"name":"Warehouse paging"}');
 perform pg_temp.wh_assert((info->>'total')::integer=57 and jsonb_array_length(info->'rows')=50,'bounded first page');
 info:=public.warehouse_inventory(f,2,'{"name":"Warehouse paging"}');
 perform pg_temp.wh_assert(jsonb_array_length(info->'rows')=7,'second page zero items');
 delete from public.user_permissions where factory_id=f and user_id=actor and module='orders' and action='create';
 perform public.configure_product_stock(f,missing,'MAKE_TO_STOCK','meter',100,200);
 update public.production_orders set status='cancelled' where request_id=r;
 r:=public.confirm_warehouse_replenishment(f,missing,'produce','meter',0,200,gen_random_uuid());
 perform pg_temp.wh_assert(r is not null,'Warehouse edit without orders:create');
 delete from public.user_permissions where factory_id=f and user_id=actor and module='warehouse' and action='edit';
 perform pg_temp.wh_assert(public.warehouse_inventory(f) is not null,'viewer reads');
 perform pg_temp.wh_error(format('select public.confirm_warehouse_replenishment(%L,%L,%L,%L,0,50,%L)',f,ext,'produce','piece',gen_random_uuid()),'permission_denied');
 perform pg_temp.wh_error(format('select public.configure_warehouse_material(%L,%L,10,50)',f,raw),'permission_denied');
 perform pg_temp.wh_assert(not has_function_privilege('anon','public.warehouse_inventory(uuid,integer,jsonb,text,text)','execute'),'anon denied');
 perform pg_temp.wh_assert(not has_function_privilege('authenticated','private.warehouse_inventory_rows(uuid)','execute'),'private helper denied');
 perform pg_temp.wh_assert(not has_table_privilege('authenticated','public.fulfillment_commands','insert'),'proof ledger protected');
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 perform pg_temp.wh_error(format('select public.warehouse_inventory(%L)',f),'permission_denied');
 set constraints all immediate;
end$test$;
rollback;
select 'Warehouse catalogue, confirmation, projection, sources, filters, pagination and permissions passed' result;
